// About screen
about_tagline: "Szybkie i niezawodne przesyłanie z komputera na PS5. Przesyłaj, montuj i przeglądaj — zaprojektowane jako uzupełnienie narzędzi po stronie PS5.",
about_what_it_does: "Co robi",
about_credits: "Twórcy",
about_website: "Strona",
about_credits_text: "Zobacz plik LICENSE, aby poznać warunki licencji.",
about_support_scene: "ps5upload to tylko jedno z wielu narzędzi. Scena PS5 jest pełna świetnej pracy: loadery, łatki jądra, narzędzia do montowania, dumpery, silniki cheatów, menedżery plików i więcej. Jeśli coś tutaj oszczędza ci czas, ludzie stojący za tamtymi narzędziami zasługują na te same podziękowania. Wesprzyj też ich.",
// About screen — feature cards (rendered from a {key, fallback} data table
// in screens/About/index.tsx, which the i18n extractor doesn't walk, so
// these are declared here by hand).
about_feat_fast_transfers_title: "Szybkie transfery",
about_feat_fast_transfers_body: "Protokół transferu AVA1 z weryfikacją BLAKE3, szyfrowanymi sesjami, wznawialnymi zadaniami i pakowaniem małych plików. Wykorzystuje sieć LAN maksymalnie.",
about_feat_native_mount_title: "Natywne montowanie obrazu",
about_feat_native_mount_body:
  "Dołącz obrazy .exfat i .ffpkg do /mnt/ps5upload/ za pomocą MDIOCATTACH + nmount — bez potrzeby zewnętrznych narzędzi.",
about_feat_works_everything_title: "Działa ze wszystkim",
about_feat_works_everything_body:
  "Wyślij dowolny plik ELF jako payload dla PS5 — ładowarki homebrew, poprawki jądra, niestandardowe narzędzia — przez :9021 za pomocą wyboru pliku.",
about_feat_hardware_title: "Podgląd sprzętu na żywo",
about_feat_hardware_body:
  "Model, numer seryjny, czas pracy, częstotliwość CPU, pamięć RAM oraz kontrola progu wiatraka — wszystko bez korzystania z interfejsu Sony.",
