nanodns_dns_howto_title: "Kieruj DNS PS5 na nanoDNS",
nanodns_dns_howto_body:
  "Na PS5: Ustawienia \u2192 Sieć \u2192 Skonfiguruj internet \u2192 (twoje połączenie) \u2192 Niestandardowe \u2192 Ustawienia DNS \u2192 Ręczne. Ustaw Główny DNS na adres z ustawienia bind w sekcji [general] pliku /data/nanodns/nanodns.ini poniżej — na przykład przy bind=127.0.0.1 ustaw Główny DNS na 127.0.0.1.",
