about_disclaimer_title: "Zastrzeżenie",
about_disclaimer_purpose: "ps5upload jest udostępniany wyłącznie do celów badawczych, edukacyjnych, interoperacyjności i tworzenia oprogramowania homebrew. Nie jest powiązany z Sony Interactive Entertainment Inc. ani przez nią wspierany. „PlayStation” i „PS5” są znakami towarowymi Sony Interactive Entertainment Inc., użytymi tu wyłącznie w celach identyfikacyjnych.",
about_disclaimer_piracy: "Używaj go wyłącznie ze sprzętem, który należy do Ciebie, i z treściami, do których masz prawa. Nie wolno go używać do kopiowania, rozpowszechniania ani uruchamiania oprogramowania, do którego nie masz praw.",
about_disclaimer_risk: "To oprogramowanie jest dostarczane „w stanie, w jakim jest”, bez jakiejkolwiek gwarancji. Używanie zmodyfikowanej konsoli może trwale ją uszkodzić, bezpowrotnie zniszczyć zapisy gier i licencje oraz doprowadzić do zablokowania konta lub konsoli. Korzystasz z niego wyłącznie na własne ryzyko i ponosisz pełną odpowiedzialność za skutki. Przed rozpoczęciem wykonaj kopię zapasową wszystkiego, czego nie możesz stracić.",
