"pkglib.fpkgsupport.lead": "Fałszywy pakiet PS5 instaluje się tylko wtedy, gdy obsługa fałszywych pakietów jest już załadowana na konsoli. Przed instalacją załaduj wszystkie trzy, w tej kolejności:",
