"fpkg.error": "Błąd konwersji",
"fpkg.lowSpace": "Mało wolnego miejsca: konwersja może potrzebować do {need} na dysku wyjściowym, a jest {free}.",
"fpkg.about": "Wskaż folder gry albo obraz do montowania .exfat lub .ffpkg. Konwerter czyta drzewo, sprawdza, czy jest wszystko, czego potrzebuje uruchamialny pakiet, i zapisuje .pkg w formacie debug do folderu wyjściowego.",
"fpkg.aboutWhere": "Konwersja działa na maszynie, na której działa silnik — tym komputerze, hoście Docker lub urządzeniu z Androidem — a nie na konsoli. Nic nie trafia na konsolę, dopóki nie zainstalujesz pakietu — strumieniowo z tego komputera albo po wcześniejszym wysłaniu na PS5.",
"fpkg.aboutSource": "Źródło musi być już odszyfrowanym drzewem gry. Instalacji retail nie da się tu rozpakować, a test poniżej o tym powie, jeśli właśnie taką wybrałeś.",
"fpkg.aboutChecks": "Co sprawdza test",
"fpkg.checkEboot": "Plik eboot.bin w katalogu głównym drzewa — moduł tytułu. Musi to być surowy ELF lub opakowany SELF; modułu podpisanego jako retail nie da się przepakować.",
"fpkg.checkParam": "sce_sys/param.json i brak sce_sys/param.sfo — param.sfo kieruje ścieżkę uruchamiania konsoli na trasę PS4.",
"fpkg.checkIcons": "36-znakowy identyfikator zawartości, obie ikony i moduł praw sce_sys/about/right.sprx.",
"fpkg.checkDrm": "Czy wartość DRM pakietu jest standardowa. Wartość darmowa lub z możliwością ulepszenia sprawia, że konsola blokuje tytuł; jest przepisywana tylko w pakiecie, a twój plik nigdy nie jest zmieniany.",
"payloads_essentials_title": "Zalecane razem z ps5upload",
"payloads_essentials_body": "Jeśli konfigurujesz konsolę po raz pierwszy, te trzy pokrywają większość tego, czego oczekuje ps5upload: kstuff-lite (łatki jądra, na których opiera się większość homebrew), ShadowMount+ (montowanie obrazów gier z pamięci) i nanoDNS (trzyma konsolę z dala od aktualizacji Sony). Wszystko inne na tej liście jest opcjonalne.",
"navigation_history": "Pokaż historię",
