"power_wake_setup_cta": "Skonfiguruj wybudzanie i logowanie",
"power_wake_offer_hint": "ps5upload może to skonfigurować za ciebie — odczyta z konsoli, czego potrzebuje. Nic do szukania, żadne inne aplikacje nie są potrzebne.",
"power_wake_working": "Konfigurowanie tej konsoli…",
"power_wake_working_detail": "Włączanie Remote Play, odczyt twojego konta z konsoli i rejestracja. Nic nie musisz robić.",
"power_wake_needs_awake": "Włącz konsolę, aby to skonfigurować — parowanie rejestruje się przez sieć, więc działa tylko, gdy konsola jest włączona. Wystarczy zrobić to raz.",
