"backport_inspecting": "Sprawdzanie zainstalowanych rodzin bibliotek…",
"backport_summary": "Gra zostanie obniżona do pary SDK z FW 4 i zostanie zainstalowany zestaw {count} bibliotek dostarczany przez {set}. Zestaw instaluje się w całości — mieszanie bibliotek z różnych gier sprawia, że backport się nie uruchamia.",
"settings_card_fakelibs": "Biblioteki backportu",
"backport_verify_unpatched": "Ten tytuł nie ma backportu",
"backport_verify_unpatched_body": "Jego eboot wciąż ma oryginalną wersję SDK, więc nie może działać na tym oprogramowaniu, niezależnie od zainstalowanych bibliotek — to nie zestaw bibliotek jest problemem. Wykonaj backport ponownie; jeśli się powtórzy, łatka SDK nie jest nakładana.",
"backport_no_larger": "Ta gra potrzebuje bibliotek, których nie ma żaden z twoich zestawów. Zaimportuj pełniejszy pakiet albo przeskanuj inną konsolę.",
"backport_verifying": "Uruchamianie i obserwacja — nieudane uruchomienie jest ponawiane, bo uruchamianie jest tak zawodne, że jedna porażka niczego nie dowodzi.",
"backport_verify_running": "Działa — czy dochodzi do rozgrywki?",
"backport_verify_running_body": "Gra nadal działa po minucie (wątków: {threads}). Nie wysypała się więc przy ładowaniu, ale to nie znaczy, że da się w nią grać — spójrz na ekran. Zostaw ją, jeśli działa, albo cofnij i spróbuj następnego zestawu.",
"backport_verify_missing": "Potrzeba więcej bibliotek",
"backport_verify_missing_body": "Gra wywołała funkcję, której nie dostarcza żadna z zainstalowanych bibliotek. Pozostało większych zestawów do wypróbowania: {count}.",
"backport_verify_wrong": "Złe biblioteki dla tej gry",
"backport_verify_wrong_body": "Ten tytuł jest poprawnie załatany, ale nie uruchomił się z tymi bibliotekami, więc to nie te, których potrzebuje. Pozostało innych zestawów do wypróbowania: {count}.",
"backport_verify_unknown": "Nie da się stwierdzić, czy zadziałało",
"backport_verify_unknown_body": "Uruchomienia dały różne wyniki, więc nie mówią nic o bibliotekach — uruchamianie samo zawodzi na tyle często, że mieszany wynik nic nie znaczy. Spróbuj uruchomić grę sam i cofnij, jeśli nie da się grać.",
"backport_get_more": "Zdobądź więcej bibliotek…",
"backport_needs_libraries": "Backport {name} wymaga zastępczych bibliotek systemowych. To pliki Sony, więc ps5upload nie może ich dołączyć — dostarczasz je raz, z gier, które posiadasz, a każdy kolejny backport z nich korzysta.",
