"joberr.ava1_refused": "PS5 odrzuciła to żądanie (kod {code}). Spróbuj ponownie; jeśli się powtarza, zaktualizuj pomocnika i aplikację do tej samej wersji i dołącz kod do zgłoszenia błędu.",
"joberr.ava1_busy": "Pomocnik PS5 jest zajęty i nie przyjął tego transferu na czas. Poczekaj, aż skończy inną pracę, i kliknij Ponów.",
"joberr.ava1_unreachable": "Nie można połączyć się z PS5. Sprawdź, czy jest włączona, w tej samej sieci i czy pomocnik działa, a potem kliknij Ponów.",
"joberr.ava1_exists": "Cel już istnieje na PS5. Wybierz Nadpisz, aby go zastąpić, albo wybierz inny cel.",
"joberr.ava1_commit_exists": "Plik został wysłany, ale nie udało się go opublikować, bo cel już istnieje. Wybierz Nadpisz, aby go zastąpić, albo wybierz inny cel.",
"joberr.ava1_cross_device": "Cel jest na innym dysku niż obszar tymczasowy, więc PS5 nie mogła przenieść pliku. Wybierz cel na tym samym dysku lub najpierw wyślij na dysk wewnętrzny.",
"joberr.ava1_wrong_console": "Urządzenie pod tym adresem nie jest PS5 sparowaną z tą aplikacją. Sprawdź adres lub sparuj tę konsolę ponownie.",
"joberr.ava1_no_identity": "Ta aplikacja nie ma jeszcze tożsamości parowania. Sparuj ją z PS5 na ekranie Połączenie i spróbuj ponownie.",
"joberr.zip_read_error": "Nie udało się odczytać pliku .zip (plik lub jego dysk mógł zniknąć w trakcie odczytu). Sprawdź, czy źródło jest nadal podłączone, i kliknij Ponów.",
"joberr.ava1_zip_corrupt": "Nie udało się odczytać tego pliku .zip: jest uszkodzony lub niekompletny. Pobierz go lub utwórz ponownie i spróbuj jeszcze raz.",
"joberr.ava1_7z_corrupt": "Nie udało się odczytać tego pliku .7z: jest uszkodzony lub niekompletny. Pobierz go lub utwórz ponownie i spróbuj jeszcze raz.",
"joberr.ava1_7z_encrypted": "Ten plik .7z jest zaszyfrowany i nie można go przesłać strumieniowo. Rozpakuj go na komputerze i wyślij folder.",
"joberr.ava1_7z_unsafe_path": "Ten plik .7z zawiera niebezpieczną ścieżkę pliku (wychodzi poza własny folder). Rozpakuj go na komputerze i wyślij folder.",
"joberr.rar_password": "Ten plik .rar wymaga hasła albo podane hasło było błędne. Wpisz poprawne hasło i spróbuj ponownie.",
"joberr.rar_corrupt": "Ten plik .rar jest uszkodzony albo brakuje niektórych części lub są w złej kolejności. Upewnij się, że są wszystkie części, i spróbuj ponownie.",
"joberr.ava1_copy_lost": "PS5 straciła ślad tego kopiowania (pomocnik się zrestartował lub połączenie zostało przerwane). Kliknij Ponów, aby zacząć od nowa.",
"joberr.ava1_copy_failed": "PS5 nie mogła dokończyć kopiowania. Sprawdź wolne miejsce oraz czy źródło i cel są nadal dostępne, i spróbuj ponownie.",
"joberr.ava1_local_io": "Ten komputer nie mógł zapisać pobranego pliku. Sprawdź uprawnienia i wolne miejsce w folderze docelowym i spróbuj ponownie.",
"joberr.ava1_bad_manifest": "PS5 wysłała listę plików, której ta aplikacja nie zrozumiała. Zaktualizuj pomocnika i aplikację do tej samej wersji i spróbuj ponownie.",
"joberr.helper_not_ava1": "Pomocnik PS5 nie działa. Wyślij go z ekranu Połączenie (lub użyj Zaktualizuj pomocnika, jeśli baner to oferuje) i spróbuj ponownie.",
"joberr.helper_not_ava1_web": "Pomocnik PS5 nie działa. Ten interfejs webowy nie może go wysłać: uruchom payload ps5upload na konsoli swoim zwykłym loaderem payloadów (lub użyj Zaktualizuj pomocnika, jeśli baner to oferuje) i spróbuj ponownie.",
"joberr.not_paired": "Ta PS5 nie zaakceptowała jeszcze tej aplikacji. Sparuj je (przycisk Sparuj…) i spróbuj ponownie.",
"joberr.helper_starting": "Pomocnik PS5 jeszcze się uruchamia. Poczekaj kilka sekund i spróbuj ponownie.",
"joberr.ava1_failed": "Pomocnik PS5 uruchomił się, ale jego serwer transferu nie. Zrestartuj konsolę i spróbuj ponownie.",
