installed_launch_smp_refused: "PS5 odmówiło uruchomienia tej gry (0x80940033), mimo że kstuff działa. ShadowMount+ montuje grę przy jej starcie, a to nie nastąpiło. Zamknij działającą grę, wyślij ShadowMount+ ponownie z Payloads, a potem naciśnij Graj.",
connection_mac_local_network_hint: "macOS może blokować tej aplikacji dostęp do sieci lokalnej. Otwórz Ustawienia systemowe → Prywatność i ochrona → Sieć lokalna, zezwól PS5Upload i sprawdź ponownie.",
batch_space_tight: "{drive}: {size} może się nie zmieścić. PS5 podczas zapisu rezerwuje około jednej piątej więcej, więc zmieści się prawdopodobnie około {fits}. Mimo to możesz spróbować.",
installed_swap_confirm_title: "Najpierw zamknąć {other}?",
installed_swap_confirm_body: "{other} jest uruchomiona, a PS5 uruchamia jedną grę naraz. Zamknąć ją i uruchomić {name}? Niezapisany postęp w {other} przepadnie.",
installed_swap_confirm_ok: "Zamknij i uruchom",
installed_swap_close_failed: "{other} nadal działa i nie udało się jej zamknąć, więc {name} nie została uruchomiona. Zamknij ją na PS5 i naciśnij Graj ponownie.",
remotePlay_np_open_payloads: "Otwórz Payloads",
library_download_resume: "Wznów pobieranie",
kept_title: "Przechowywane przez ps5upload",
kept_intro: "Foldery, które ps5upload sam zapisuje na tej konsoli, i ile każdy zajmuje. Pliki tymczasowe i testowe można wyczyścić; twoje pakiety i kopie zapisów są stąd tylko otwierane, nigdy usuwane.",
kept_measuring: "Mierzenie…",
kept_nothing: "ps5upload niczego nie przechowuje na tej konsoli.",
kept_pkg_library: "Biblioteka pakietów",
kept_pkg_temp: "Pliki tymczasowe pakietów",
kept_backups: "Kopie zapisów",
kept_tests: "Pliki testowe",
kept_at_least: "co najmniej {size}",
kept_files: "Pliki: {count}",
kept_clean: "Wyczyść",
kept_open: "Otwórz w Plikach",
kept_clean_title: "Usunąć te pliki z PS5?",
kept_clean_body: "Cała zawartość {path} ({size}) zostanie usunięta. To pozostałości, które ps5upload może odtworzyć; biblioteka pakietów i kopie zapisów pozostają nietknięte.",
library_move_retry: "Spróbuj przenieść ponownie",
volumes_pkg_copies_here: "Kopie pakietów są tutaj",
volumes_store_pkg_copies: "Przechowuj tu kopie pakietów",
volumes_pkg_copies_hint: "Co robi ten wybór: „Prześlij i zainstaluj” najpierw kopiuje plik .pkg na PS5, a potem instaluje z tej kopii. Tutaj ustawiasz tylko, na którym dysku leżą te kopie. Nie zmienia to miejsca instalacji gier (decyduje o tym PS5 w swoich ustawieniach pamięci), a „Strumieniuj i zainstaluj” nie zostawia żadnej kopii. Jeśli wybrany dysk nie jest podłączony, kopie trafiają do pamięci wewnętrznej.",
saves_auto_folder_label: "Folder kopii",
captures: "Zrzuty i klipy",
captures_title: "Przechwycone",
"arcpkg.choose": "Wybierz archiwum…",
"arcpkg.help": "Dla pliku .zip, .7z lub .rar, który zawiera jeden lub więcej plików .pkg w dowolnych folderach. Rozpakowywane są tylko pakiety, od razu na PS5 (na tym komputerze nic nie jest wypakowywane), a potem instalowane po kolei: najpierw gra podstawowa, potem aktualizacja, potem DLC. Wieloczęściowy RAR (.part1.rar, .part2.rar…) jest obsługiwany: wybierz pierwszą część, a pozostałe trzymaj obok. O hasło zapytamy, gdy RAR go wymaga; ZIP i 7z z hasłem nie są obsługiwane.",
"arcpkg.keepsRunning": "To działa dalej, gdy otworzysz inny ekran, i jest też widoczne w „Zadaniach”.",
"arcpkg.notArchive": "Ten plik nie jest archiwum .zip, .7z ani .rar.",
"arcpkg.pick": "Wybierz archiwum",
"arcpkg.title": "Zainstaluj pakiety z archiwum",
"install.library.title": "Kopie pakietów na PS5",
"install.stream.file.help": "Wybierz plik .pkg lub .fpkg albo upuść go w dowolnym miejscu tego okna. Nie zamykaj aplikacji do końca instalacji; postęp widać w kolejce powyżej i w „Zadaniach”.",
"install.stream.file.title": "Zainstaluj plik pakietu",
"install.tab.stream.lead": "PS5 instaluje prosto z tego komputera lub z linku. Na PS5 nie trafia wcześniej żadna kopia, więc nie potrzeba tam wolnego miejsca, i jest to najpewniejszy sposób instalacji.",
"install.tab.upload.lead": "Pakiet jest najpierw kopiowany na PS5, a potem instalowany z tej kopii. Użyj tego, gdy PS5 nie może połączyć się z tym komputerem (strumieniowanie kończy się błędem sieci) albo gdy chcesz trzymać pakiety na PS5 i instalować je ponownie później bez tego komputera.",
"install.upload.file.browser": "Kopiowanie pakietu na PS5 stąd wymaga aplikacji na komputer. W interfejsie WWW użyj „Strumieniuj i zainstaluj” albo zainstaluj poniżej pakiety, które już są na PS5.",
"install.upload.file.help": "Wybierz plik .pkg lub .fpkg. Kopia wymaga wolnego miejsca na PS5 na cały pakiet i zostaje na liście poniżej, dopóki jej nie usuniesz.",
"install.upload.file.title": "Skopiuj pakiet na PS5 i zainstaluj go",
"linkcard.confirm.direct": "PS5 sama pobiera pakiet z linku i instaluje go. Po rozpoczęciu ten komputer nie jest już potrzebny, a postęp widać na PS5 (Pobrane), nie tutaj. Jeśli PS5 nie może dotrzeć do linku, aplikacja przekaże go przez ten komputer. Ponowna instalacja na już zainstalowanej grze może ją usunąć, jeśli instalator Sony zawiedzie. Używaj tylko linków do pakietów, którym ufasz i które masz prawo instalować.",
"linkcard.confirm.download": "Ten komputer najpierw zapisuje cały pakiet na dysku, a potem instaluje go na PS5. Musi pozostać włączony do końca obu etapów i mieć wolne miejsce na pakiet. Ponowna instalacja na już zainstalowanej grze może ją usunąć, jeśli instalator Sony zawiedzie. Używaj tylko linków do pakietów, którym ufasz i które masz prawo instalować.",
"linkcard.confirm.stream": "Ten komputer pobiera pakiet i od razu przekazuje go do PS5, więc musi pozostać włączony i połączony do końca instalacji. Nic nie jest zapisywane na dysku. Ponowna instalacja na już zainstalowanej grze może ją usunąć, jeśli instalator Sony zawiedzie. Używaj tylko linków do pakietów, którym ufasz i które masz prawo instalować.",
"linkcard.confirm.title": "Zainstalować z tego linku?",
"linkcard.fact.awake": "Nie usypiaj tego komputera",
"linkcard.fact.can_close": "Możesz zamknąć aplikację",
"linkcard.fact.disk": "Wymaga miejsca na dysku tutaj",
"linkcard.fact.no_disk": "Nie wymaga miejsca na dysku",
"linkcard.fact.progress_here": "Postęp widać tutaj",
"linkcard.fact.progress_ps5": "Postęp widać na PS5",
"linkcard.forget": "Usuń z listy",
"linkcard.help": "Wklej bezpośredni link do pliku .pkg. Na PS5 nic nie jest wcześniej kopiowane, więc gra o rozmiarze 100 GB nie wymaga tam dodatkowego miejsca.",
"linkcard.how": "Jak ma zostać pobrany?",
"linkcard.insecure": "Pomiń sprawdzanie certyfikatu",
"linkcard.insecure_hint": "Dla własnego serwera lub strony z wygasłym certyfikatem. Działa tutaj, bo to ten komputer nawiązuje połączenie.",
"linkcard.install": "Zainstaluj z linku",
"linkcard.mode.direct": "Niech PS5 pobierze sama",
"linkcard.mode.direct_body": "PS5 sama pobiera link. Musi mieć do niego dostęp, a adres musi być krótki (długi aplikacja skraca i wtedy musi pozostać otwarta).",
"linkcard.mode.download": "Najpierw pobierz tutaj, potem zainstaluj",
"linkcard.mode.download_body": "Ten komputer zapisuje cały pakiet, a potem go instaluje. Najwolniejszy sposób, ale jeśli link wygaśnie lub się zerwie, wystarczy ponowić pobieranie.",
"linkcard.mode.stream": "Strumieniuj przez ten komputer",
"linkcard.mode.stream_body": "Ten komputer pobiera kilkoma połączeniami i od razu przekazuje dane do PS5. Zwykle najszybszy sposób, działa też wtedy, gdy do linku ma dostęp tylko ten komputer.",
"linkcard.name": "Nazwa (opcjonalnie)",
"linkcard.name_hint": "Nazwa jest pokazywana zamiast adresu w kolejce, w „Zadaniach” i w ostatnich linkach, żeby łatwo rozróżnić linki i ponowić właściwy.",
