"netdoctor.help": "Sprawdza połączenie między tym komputerem a PS5 i wypisuje to, co spowalnia transfery, zaczynając od najważniejszych rzeczy. Uruchamia też test prędkości, chyba że jeden był uruchomiony w ostatnich minutach.",
