"netdoctor.load_latency.balloons.detail": "PS5 odpowiada w {idle} ms, gdy sieć jest spokojna, ale w {loaded} ms podczas wysyłania pliku. Router lub łącze Wi-Fi, które zatrzymuje zbyt dużo danych, spowalnia każdy transfer.",
"netdoctor.load_latency.balloons.fix": "Użyj kabla sieciowego, zbliż się do routera albo włącz w routerze ustawienie Smart Queue lub QoS.",
"netdoctor.load_latency.balloons.title": "Odpowiedzi zwalniają podczas wysyłania",
