"netdoctor.mtu.mismatch.fix": "Ustaw po obu stronach zwykły rozmiar 1500: wyłącz ramki jumbo na tym komputerze, a w PS5 ustaw MTU na automatyczne w zaawansowanych ustawieniach połączenia internetowego.",
