"netdoctor.title": "Diagnozuj wolne transfery",
stop: "Zatrzymaj",
activity_description_v2: "Wszystko, co aplikacja robi i robiła na twoich konsolach: wysyłanie, pobieranie, instalacje i operacje na plikach. Każdą z nich możesz stąd zatrzymać lub ponowić. Przechowywanych jest 100 ostatnich, także po ponownym uruchomieniu.",
fw_spoof_subtitle_v2: "Sprawdza, czy wersja oprogramowania zgłaszana przez tę PS5 została zmieniona przez payload spoofujący, żebyś znał prawdziwą wersję przed instalacją czegoś, co od niej zależy.",
health_subtitle_v2: "Sprawdza, czy PS5, ta aplikacja i sieć między nimi działają, podpowiada, co naprawić, gdy nie działają, i mierzy prędkość przesyłania plików między nimi.",
remotePlay_subtitle_v2: "Skonfiguruj tę PS5 do gry zdalnej i uzyskaj kod PIN, który łączy z nią aplikację PS Remote Play.",
saves_description_v2: "Zapisane dane na PS5, jeden wpis na grę. Zrób kopię zapasową zapisów gry do pliku .zip na tym komputerze i przywróć ją później.",
shell_description_v2: "Wpisuj polecenia wykonywane na PS5 w procesie pomocnika. Dla zaawansowanych użytkowników. Wynik jest ograniczony do 256 KB na polecenie; strzałki w górę i w dół przywołują wcześniejsze polecenia.",
"arcpkg.links.go": "Pobierz pliki: {count}",
"arcpkg.links.help": "Wklej bezpośredni link do archiwum albo do każdej części podzielonego archiwum, po jednym w wierszu. Pliki są pobierane na ten komputer (Downloads/ps5upload), który musi mieć miejsce na wszystkie; potem pakiety z nich są rozpakowywane na PS5, jak opisano wyżej.",
"arcpkg.links.kept": "Pobrane pliki ({count}) są w {dir}. Zostają, żeby można było ponowić instalację; usuń je, gdy skończysz.",
"arcpkg.links.progress": "Pobieranie pliku {n} z {count} na ten komputer…",
"arcpkg.links.title": "Archiwum jest dostępne pod linkami do pobrania",
"arcpkg.noFirstPart": "Pliki zostały pobrane, ale żaden z nich nie jest pierwszą częścią archiwum (.zip, .7z, .rar lub .part1.rar). Sprawdź linki.",
"fpkg.image.done": "Obraz gry został zapisany i odczytany kontrolnie. Skopiuj go na dysk PS5 („Wyślij”), a ShadowMount+ go zamontuje.",
"fpkg.image.what": "Jeden plik, który kopiujesz na dysk PS5, a ShadowMount+ go montuje i pokazuje na ekranie głównym. Nic nie jest instalowane.",
"fpkg.image.folderOnly": "Obrazem gry może stać się tylko folder gry na tym komputerze.",
"fpkg.image.folderOnly_v2": "Tylko folder gry (na tym komputerze, zapisanym serwerze lub PS5) może stać się obrazem gry.",
"fpkg.image.folderOnly_v4": "Obrazem gry może stać się tylko folder gry, obraz gry lub archiwum (.zip, .7z, .rar) z grą w środku; archiwum jest najpierw rozpakowywane do folderu wyjściowego.",
"fpkg.card.make": "② Co utworzyć",
"fpkg.card.options_v2": "③ Opcje",
"fpkg.card.run_v2": "④ Utwórz i zainstaluj",
"fpkg.options.image": "Obraz",
"fpkg.make.pkg_title": "Pakiet (.pkg)",
"fpkg.make.pkg_body": "Instaluje się na PS5 jak gra ze sklepu, strumieniowo stąd lub po wysłaniu. Gry PS4 działają na każdym firmware; gry PS5 do 11.60.",
"fpkg.make.image_title": "Obraz gry",
"fpkg.make.image_body": "Jeden plik na dysku PS5, który ShadowMount+ montuje i pokazuje na ekranie głównym. Nic nie jest instalowane, a działa na firmware, na którym pakiet PS5 nie ruszy.",
"fpkg.make.recommended": "Zalecane",
"fpkg.make.recommended_fw": "Zalecane na FW {fw}",
"fpkg.make.pick_game": "Sprawdź grę w ①, a lepszy wybór dla twojej PS5 zostanie oznaczony.",
"fpkg.make.why_image": "Ta gra PS5 zainstalowałaby się jako pakiet, ale nie ruszy na FW {fw}; jako obraz działa.",
"fpkg.make.why_pkg": "Pakiet to zwykły wybór: instaluje się i działa jak każda inna gra.",
"fpkg.run.summary": "Tworzy {what} gry {title} w {dir}.",
"fpkg.run.what_image": "obraz gry {ext}",
"fpkg.run.what_pkg": "pakiet (.pkg)",
connection_payload_engine_unreachable: "Aplikacja nie mogła połączyć się z własnym silnikiem na tym komputerze, więc nie wie, czy pomocnik uruchomił się na PS5. To nie jest problem PS5: komunikat na górze okna podaje przyczynę i może zrestartować silnik. Potem naciśnij ponownie „Wyślij pomocnika”. ({error})",
"engine_problem.missing.fix": "Przywróć ps5upload-engine z kwarantanny antywirusa (lub zezwól na niego) albo zainstaluj aplikację ponownie.",
"engine_problem.missing.why": "W folderze aplikacji brakuje programu silnika. Oprogramowanie zabezpieczające czasem przenosi go do kwarantanny.",
"engine_problem.port.fix": "Naciśnij „Uruchom silnik ponownie”. Jeśli to nie pomoże, zezwól na ps5upload-engine w zaporze lub antywirusie i uruchom aplikację ponownie.",
"engine_problem.port.why": "Coś zajmuje adres silnika ({url}), ale nie odpowiada: inny program na tym porcie albo oprogramowanie zabezpieczające blokujące połączenia z nim.",
"engine_problem.proxy.fix": "Wyłącz proxy lub VPN dla adresów lokalnych (127.0.0.1) albo uruchom aplikację bez ustawienia http_proxy / ALL_PROXY.",
"engine_problem.proxy.why": "Żądania do silnika trafiły do proxy ustawionego na tym komputerze zamiast do silnika.",
"engine_problem.remote.fix": "Sprawdź, czy silnik (kontener Docker lub inny komputer) działa i jest osiągalny pod tym adresem, albo zmień go w Ustawieniach.",
"engine_problem.remote.why": "Silnik, którego ta aplikacja ma używać ({url}), nie odpowiada.",
"engine_problem.restart": "Uruchom silnik ponownie",
"engine_problem.slow.fix": "Naciśnij „Uruchom silnik ponownie”. Może to też powodować zapora lub antywirus filtrujący połączenia lokalne: zezwól na ps5upload-engine.",
"engine_problem.slow.why": "Silnik działa, ale nie odpowiada.",
"engine_problem.stopped.fix": "Naciśnij „Uruchom silnik ponownie”. Jeśli znowu się zatrzyma, ekran Logi pokaże dlaczego.",
"engine_problem.stopped.why": "Silnik nie działa: zatrzymał się albo w ogóle nie wystartował.",
"engine_problem.title": "Aplikacja nie może połączyć się ze swoim silnikiem na tym komputerze",
"engine_problem.web.fix": "Sprawdź, czy serwer (kontener Docker) działa, i odśwież tę stronę.",
"engine_problem.web.why": "Ta strona straciła połączenie z serwerem ps5upload, z którego pochodzi.",
gate_engine_down_body_v2: "Ten ekran potrzebuje silnika aplikacji, który nie odpowiada. Komunikat na górze okna podaje przyczynę i może go zrestartować.",
"profile.np.body": "Sprawia, że PS5 traktuje zalogowane konto jak zalogowane do PlayStation Network, bez kontaktu z Sony. Niektóre funkcje konsoli są dostępne tylko dla zalogowanego konta, w tym Remote Play. Używa np-fake-signin autorstwa earthonion, pobieranego ze strony projektu po naciśnięciu przycisku.",
"profile.np.confirm_title": "Zalogować to konto?",
"profile.np.failed": "Logowanie nie zostało wykonane",
"profile.np.fetching": "Pobieranie np-fake-signin…",
"profile.np.sending": "Wysyłanie na PS5…",
"profile.np.sent": "np-fake-signin {version} został uruchomiony na PS5. Uruchom PS5 ponownie, aby zakończyć; konto będzie wtedy widoczne jako zalogowane, a Ustawienia > System > Remote Play da się włączyć.",
"profile.np.sign_in": "Zaloguj",
"profile.np.state_loading": "Odczytywanie konta…",
"profile.np.state_no_slot": "Żadne konto powyżej nie nazywa się {user}, więc np-fake-signin by się zatrzymał. Nadaj kontu tę samą nazwę co zalogowanemu użytkownikowi albo aktywuj dla niego konto.",
"profile.np.state_no_user": "Na PS5 nie jest zalogowany żaden użytkownik. Zaloguj się na wybrany profil i wróć.",
"profile.np.state_not_activated": "{user} (konto {slot}) nie ma jeszcze identyfikatora konta. Najpierw aktywuj je w sekcji Konta powyżej.",
"profile.np.state_ready": "Gotowe: {user} (konto {slot}) jest aktywowane.",
"profile.np.step_activate": "Konto potrzebuje identyfikatora konta. Konto połączone z PSN go ma; w przeciwnym razie aktywuj je w sekcji Konta powyżej (aktywacja offline).",
"profile.np.step_run": "Naciśnij Zaloguj, gdy ten użytkownik jest zalogowany na PS5. Program uruchomi się raz i zakończy.",
"profile.np.title": "Zaloguj do PlayStation Network (offline)",
