trace_measuring: "Pomiar",
trace_what: "Dla obrazu LZ4, który ładuje się tak, jak gra gra. Pomiarowa wersja ampr_emu zapisuje każdy plik czytany podczas gry; profil zbudowany z tych sesji dobiera rozmiary bloków, układ i pamięć podręczną dla każdego pliku zamiast jednego zgadywania. Convert używa go przy tworzeniu obrazu LZ4 tej gry.",
