"pkg.sony_80b21104": "PS5 nie przyjęła tego pakietu (0x80B21104). Jeśli inne pakiety instalują się na tej konsoli, problem jest w tym pliku: najczęściej to nowa gra, której pakiet zrobiono narzędziami nowszymi, niż rozumie firmware tej konsoli, albo pakiet, który nie jest kompilacją z fałszywym podpisem (FPKG). Użyj pakietu zrobionego dla twojego firmware (backport) albo zainstaluj grę z pominięciem instalatora: skopiuj jej folder gry lub obraz gry (.exfat lub .ffpfsc) dla ShadowMount+ przez Wyślij.",
