fs_send_dial_hint: "Zostaw puste, by łączyć się z własnym adresem konsoli. Dla ps5-tailscale ustaw lokalne przekierowanie na konsoli wysyłającej (jej strona stanu: 127.0.0.1:19120 → druga konsola:9120) i wpisz tu 127.0.0.1:19120. O tym, kto może wysyłać, decydują klucze konsol i jednorazowy bilet, nie adres.",
