"fpkg.image.lz4_no_ampr": "Ta gra nie czyta plików przez AMPR, więc nic w niej nie obsłuży paczek zasobów. Skompresuj ją zamiast tego do .ffpfsc: ShadowMount+ rozpakowuje to dla każdej gry.",
