err_launch_homebrew_refused: "PS5 odmówiła uruchomienia tego tytułu (0x80940033). Konsola nie uruchamia teraz homebrew ani gier z fałszywych pakietów: wczytaj kstuff (albo uruchom ponownie i wykonaj jailbreak jeszcze raz), a potem spróbuj ponownie.",
"fakegame.fw.body": "Zainstaluje się, ale fałszywych pakietów gier PS5 nie da się uruchomić na firmware nowszym niż {last}. Pakiety PS4 działają, a aplikacje homebrew PS5 uruchamiają się normalnie.",
"fakegame.fw.launch": "Fałszywych pakietów gier PS5 nie da się uruchomić na firmware nowszym niż {last} (ta konsola ma {fw}). Jeśli ta gra została zainstalowana z fałszywego pakietu, to dlatego się nie uruchamia. Pakiety PS4 działają.",
