install_path_fallback_hint: "Ostateczność dla pakietu, który już jest na PS5, gdy PS5 odrzuca go z własnej pamięci i nie może też pobrać go z tego komputera. Używane tylko dla niezainstalowanej gry podstawowej, więc niczego nie może usunąć. Niesprawdzone: działało na firmware 11.20, a na 13.60 jest odrzucane. Jeśli spróbujesz, daj znać, czy zadziałało.",
