"minion_lan_hint": "Wył.: otwiera go tylko przeglądarka samej konsoli PS5. Wł.: telefon, tablet lub komputer w tej samej sieci też mogą go otworzyć, więc może to zrobić każdy w tej sieci. Włączaj tylko w domu.",
"minion_open_here": "Otwórz tutaj",
"minion_remove_note": "Usunięcie wyłącza Minion i kasuje to, co zapisuje na PS5: ulubione i ostatnie foldery w Plikach, pamięć podręczną biblioteki gier oraz dziennik kontrolera. Udziały sieciowe, kody i kopie zapasowe zostają, bo korzysta z nich także aplikacja na PC.",
"minion_remove": "Usuń Minion z tej konsoli PS5…",
"minion_remove_title": "Usunąć PS5Upload Minion?",
"minion_remove_confirm": "Jego kafelek na ekranie głównym i strona znikną, a własne pliki na PS5 zostaną skasowane. Pomocnik od teraz będzie go trzymać wyłączonego. Możesz go tu włączyć z powrotem w dowolnej chwili.",
"minion_remove_go": "Usuń",
"minion_removed_done": "Minion został usunięty: jego kafelek i strona zniknęły, a {n} jego plików na PS5 skasowano. Pozostaje wyłączony, nawet po ponownym uruchomieniu pomocnika, dopóki nie włączysz go tutaj.",
"fs_dragout_n_items": "Elementy: {n}",
"fs_dragout_over_cap": "Jedno przeciągnięcie pobiera do 4 GB. Aby pobrać więcej, kliknij prawym przyciskiem → Pobierz.",
"fs_drag_hint_move": "Przeciągnij pliki i foldery poza okno, aby skopiować je na ten komputer, albo do okna, aby skopiować je tutaj. Przytrzymaj Alt (⌥ Option na Macu) podczas przeciągania, aby przenieść je do folderu tutaj.",
"fs_drag_hint": "Przeciągnij pliki i foldery poza okno, aby skopiować je na ten komputer, albo do okna, aby skopiować je tutaj.",
"fs_browser_drop_folder": "W przeglądarce nie można upuszczać folderów",
"fs_browser_drop_folder_body": "Upuść pliki z jego wnętrza albo użyj aplikacji na komputer, aby kopiować całe foldery.",
"collection.send_free_space": "Zwolnij miejsce",
