"rp_keep_hint": "Inne ekrany podtrzymują strumień; tyle czeka, gdy żadne okno go nie pokazuje (zamknięte lub przeładowane), zanim się zakończy.",
"rp_game_mode_mac": "Podczas gry komputer i ekran nie usypiają. Pełny ekran włącza też tryb gry (macOS 14 i nowsze).",
"rp_game_mode_ios": "Tryb gry włącza się, gdy aplikacja wypełnia ekran (iOS i iPadOS 18 i nowsze).",
"rp_game_mode_windows": "Podczas gry komputer i ekran nie usypiają. Windows nie pozwala aplikacji włączyć trybu gry; zobacz FAQ.",
"rp_game_mode_linux": "Podczas gry komputer i ekran nie usypiają, a GameMode (gamemoded) włącza się, jeśli jest zainstalowany.",
"rp_game_mode_android": "Podczas gry ekran pozostaje włączony, urządzenie w miarę możliwości trzyma stałą wydajność, a telewizor przez HDMI jest proszony o tryb gry.",
"rp_set_controls": "Sterowanie",
"rp_capture_pointer": "Kliknięcie obrazu ukrywa wskaźnik",
"rp_capture_pointer_hint": "Esc pokazuje go ponownie.",
"rp_rumble": "Wibracje kontrolera",
"rp_dualsense": "Efekty DualSense",
"rp_dualsense_hint": "Z kontrolerem DualSense podłączonym do tego komputera: adaptacyjne triggery, a po podłączeniu przez USB także haptyka. Działa od następnego uruchomienia.",
"rp_mic_setting": "Mikrofon (eksperymentalny)",
"rp_mic_setting_hint": "Dodaje przycisk mikrofonu do czatu głosowego. Działa od następnego startu.",
"rp_touch_controls": "Kontroler na ekranie",
"rp_touch_auto": "Na ekranach dotykowych",
"rp_touch_on": "Zawsze",
"rp_touch_off": "Nigdy",
"rp_controls_hint": "Działa też kontroler: podłącz go lub sparuj z tym urządzeniem. Shift + przeciągnięcie na obrazie to palec na touchpadzie.",
"rp_hid_touchpad": "Użyj panelu dotykowego DualSense",
"rp_hid_touchpad_hint": "Przeglądarka zapyta o kontroler: wybierz DualSense.",
"rp_hid_touchpad_on": "Panel dotykowy DualSense jest odczytywany w tej przeglądarce.",
"rp_settings": "Ustawienia",
"rp_running_elsewhere": "Graj działa na {name}",
"rp_show_here": "Pokaż tutaj",
"rp_running_elsewhere_body": "Uruchomiono go w innym oknie lub przed przeładowaniem tej strony i nadal trwa.",
"rpg_user_title": "Zaloguj użytkownika na PS5",
"rpg_user_body": "Na konsoli wybierz użytkownika, którym będziesz grać. Nikt nie musi zostać przed ekranem, ale użytkownik musi być zalogowany. Jeśli użytkownik ma kod dostępu, Graj zapyta o niego po naciśnięciu Start.",
"rpg_account_title": "Nadaj temu użytkownikowi identyfikator konta",
"rpg_account_body": "Remote Play paruje się przez identyfikator konta. Użytkownik połączony z PlayStation Network już go ma; użytkownik offline potrzebuje go ustawionego w sekcji Użytkownicy powyżej (dowolny identyfikator działa; zapisz go, zapisy gry utworzone później są z nim powiązane).",
"rpg_signin_title": "Zaloguj konto do PlayStation Network (offline)",
"rpg_signin_body": "PS5 pozwala korzystać z Remote Play tylko zalogowanemu kontu. Jeśli ustawienie Remote Play na konsoli jest wyszarzone, uruchom poniżej logowanie offline (nic nie jest wysyłane do Sony), a potem uruchom PS5 ponownie. Można to cofnąć.",
"rpg_signin_fix": "Przejdź do logowania",
"rpg_service_title": "Włącz Remote Play",
"rpg_service_body": "Ustawienia › System › Remote Play › Włącz Remote Play. Aplikacja może włączyć to za Ciebie, a od oprogramowania 10.00 także zezwolić na to temu użytkownikowi. Jeśli potem Start mówi, że Remote Play jest wyłączone, włącz je w Ustawieniach samej PS5: liczy się przełącznik na konsoli.",
"rpg_rest_title": "Pozwól wybudzać PS5 z trybu spoczynku",
"rpg_rest_body": "Ustawienia › System › Oszczędzanie energii › Funkcje dostępne w trybie spoczynku: włącz „Pozostań połączony z internetem” i „Włącz włączanie PS5 przez sieć”. Bez nich konsoli w trybie spoczynku nie da się wybudzić, a jej sieć zasypia po kilku sekundach. Tylko konsola może je pokazać.",
"rpg_pair_title": "Sparuj tę aplikację z konsolą",
"rpg_pair_body": "Połączenie › Wybudź i zaloguj › Skonfiguruj. Jedno kliknięcie rejestruje tę aplikację w PS5 (jak parowanie aplikacji PS Remote Play) i przechowuje jej klucze na tym komputerze. Korzystają z nich streaming, wybudzanie i logowanie; powtórz to po zresetowaniu konsoli lub zmianie użytkownika.",
"rpg_play_title": "Graj",
"rpg_play_body": "Otwórz Remote Play i naciśnij Start: aplikacja wybudzi konsolę, jeśli jest w spoczynku, zaloguje i zacznie streamować. Graj kontrolerem podłączonym do tego komputera, klawiaturą lub dotykiem. Aby zamiast tego użyć aplikacji PS Remote Play od Sony lub chiaki-ng, poproś poniżej o PIN i wpisz go tam.",
"rpg_play_fix": "Otwórz Remote Play",
"rpg_title": "Skonfiguruj Remote Play",
"rpg_progress": "Ukończono {done} z {n} sprawdzanych kroków",
"rpg_on_console": "sprawdź na konsoli",
"rpg_trouble": "Jeśli nadal nie działa",
"rpg_t_start_q": "Start jest wyszarzony na ekranie Graj.",
"rpg_t_start_a": "Ta aplikacja nie jest jeszcze sparowana z tą konsolą: wykonaj krok 6 (Połączenie › Wybudź i zaloguj › Skonfiguruj).",
"rpg_t_pair_q": "Konfiguracja parowania zgłasza, że nie ma zalogowanego użytkownika z aktywowanym kontem.",
"rpg_t_pair_a": "Kroki 1 i 2: zaloguj użytkownika na PS5 i nadaj mu identyfikator konta, a potem spróbuj ponownie.",
"rpg_t_grey_q": "Ustawienie Remote Play na samej PS5 jest wyszarzone.",
"rpg_t_grey_a": "Konto nie jest zalogowane do PlayStation Network. Uruchom logowanie offline (krok 3) i uruchom PS5 ponownie.",
"rpg_t_wake_q": "Konsola się nie wybudza albo wybudza się, ale zostaje na ekranie wyboru użytkownika.",
"rpg_t_wake_a": "Sprawdź krok 5 na konsoli. Jeśli użytkownik ma kod dostępu, wpisz go, gdy aplikacja o niego poprosi (po Start lub Wybudź i zaloguj). Jeśli konsolę zresetowano lub zmienił się użytkownik, skonfiguruj parowanie ponownie (krok 6).",
"rpg_t_black_q": "Obraz pozostaje czarny, przycina się albo dźwięk trzeszczy.",
"rpg_t_black_a": "Użyj połączenia kablowego lub Wi-Fi 5 GHz dla PS5 i tego komputera i spróbuj 720p lub 30 fps w ustawieniach Remote Play. Zapora na tym komputerze musi zezwalać aplikacji na dostęp do sieci lokalnej (Remote Play używa portów TCP i UDP 9295–9304). W przeglądarce użyj aktualnego Chrome, Edge lub Safari: obraz wymaga WebCodecs.",
"rpg_t_busy_q": "Pojawia się komunikat, że PS5 wciąż kończy ostatnią sesję albo że streamuje inna konsola.",
"rpg_t_busy_a": "Naraz streamuje jedna konsola, a PS5 potrzebuje do 30 sekund po zakończeniu sesji. Zatrzymaj drugi strumień, chwilę odczekaj, a potem ponownie naciśnij Start.",
"rpg_t_restrict_q": "Po logowaniu offline gry proszą o wyłączenie ograniczeń konsoli.",
"rpg_t_restrict_a": "Użyj Cofnij logowanie na tej stronie i uruchom ponownie albo znieś ograniczenie w Ustawienia › Rodzina i kontrola rodzicielska › Ograniczenia konsoli PS5 (kod 0000, o ile go nie zmieniono).",
