"mesh_rp_started": "{name} zaczął grać na tej konsoli",
"rp_keys_body3": "Kliknij obraz, aby grać na klawiaturze; Esc oddaje wskaźnik. Dwuklik włącza pełny ekran; tam krótkie Esc to Kółko, a przytrzymanie Esc wychodzi z pełnego ekranu. Klawisze, dźwięk i więcej w Ustawieniach.",
"rp_play_description2": "Przesyłaj obraz z PS5 do tej aplikacji i graj kontrolerem, klawiaturą lub dotykiem. Sama wybudza konsolę z trybu spoczynku i gra trwa, gdy korzystasz z innych ekranów.",
