"dump_decrypt_risk": "Odszyfrowanie może zawiesić konsolę",
"dump_decrypt_risk_body": "Aby odszyfrować, pomocnik dla każdego pliku wykonywalnego na chwilę podmienia część systemu używaną przez wszystkie programy. Jeśli gra w tym momencie odczyta plik, konsola może się zawiesić i wymagać twardego wyłączenia. Pozostań na ekranie startowym gry w trakcie. Tylko firmware do 13.60; na nowszym zrzut to zwykła kopia.",
