"notif_app_empty": "Brak powiadomień",
"notif_app_hint": "To, o czym informował Cię ps5upload: zakończone lub nieudane przesyłania i instalacje, aktualizacje. Dzwonek u góry pokazuje najnowsze. Przejrzenie tej listy oznacza ją jako przeczytaną.",
"notif_ps5_hint": "Wiadomości, które ps5upload wyświetlił na ekranie Twojej PS5 (PIN Remote Play, włączony kod), odczytywane z jego pomocnika co 5 sekund. To nie jest panel powiadomień samej PS5.",
