"send_title_v2": "Prześlij i zainstaluj",
"collection.send_many_body_v2": "Każda PS5 dostaje to, czego jej brakuje: pakiet gry albo jej folder, obraz lub archiwum, a do posiadanych gier nowsze aktualizacje i DLC. Pakiety są strumieniowane z tego komputera; reszta trafia na dysk ustawiony w „Prześlij i zainstaluj”, do folderu homebrew.",
"first_run_step4_body_v3": "Włóż do PS5 pendrive z obrazami gier .ffpkg, a ShadowMount+ automatycznie je zamontuje — pojawią się w Grach. Aby wysłać inne pliki lub zainstalować pakiety .pkg, użyj „Prześlij i zainstaluj”.",
"first_run_go_upload_v2": "Otwórz Prześlij i zainstaluj",
"fpkg.aboutFake_v2": "Wynikiem jest fałszywy pakiet, więc przed instalacją konsola musi mieć załadowaną obsługę fałszywych pakietów: kstuff (wersja z obsługą fałszywych pakietów PS5), a53_ppr_install_fast.elf i shadowmountplus.elf, w tej kolejności. „Prześlij i zainstaluj” mówi to samo obok swoich przycisków instalacji.",
"fpkg.openUpload_v2": "Otwórz Prześlij i zainstaluj",
"connection_step3_hint_v3": "Otwórz „Prześlij i zainstaluj” i upuść folder gry, obraz .exfat lub .ffpkg albo pakiet .pkg. Wysłane obrazy i foldery są widoczne na stronie gry w Gry, gdzie Montuj umieszcza je na ekranie głównym PS5.",
"connection_go_upload_v2": "Otwórz Prześlij i zainstaluj",
"netdoctor.speed_cap.on.fix_v2": "Usuń limit w „Prześlij i zainstaluj”, jeśli go nie potrzebujesz.",
"payloads_fpkg_ppr_note_v2": "Instalowanie fałszywych pakietów wymaga też a53_ppr_install_fast.elf, którego nie ma na tej liście: nie ma gotowego pliku do pobrania, buduje się go ze źródeł na GitHubie. „Prześlij i zainstaluj” wymienia wszystko, czego potrzebują fałszywe pakiety, po kolei.",
"fs_extract_next_pkgs_v2": "Zawiera pakiety: {n}. Zainstaluj je w „Prześlij i zainstaluj” albo z ich wiersza tutaj.",
"game_hub_no_addons_v2": "Brak przygotowanych pakietów DLC dla tego tytułu. Wyślij jeden przez „Prześlij i zainstaluj”.",
"game_hub_open_install_v2": "Otwórz Prześlij i zainstaluj",
"bandwidth_cap_off_hint_v3": "Bez limitu. Ustaw go, jeśli przesyłanie zapycha Wi-Fi/LAN i spowalnia inne urządzenia. Dotyczy każdego przesyłania, z „Prześlij i zainstaluj”, kolejki i Plików, od następnego uruchomionego.",
"queue_links_cleared_body_v2": "{n} link(i) instalacyjnych nie zachowano po ponownym uruchomieniu — linki nigdy nie są zapisywane na dysku. Dodaj je ponownie w „Prześlij i zainstaluj”.",
"game_hub_no_updates_v2": "Brak przygotowanych pakietów aktualizacji dla tego tytułu. Wyślij jeden przez „Prześlij i zainstaluj”.",
"pkglib.fpkgsupport.firmware": "Fałszywe pakiety PS5 (PS5 FPKG) nie są jeszcze obsługiwane w firmware nowszym niż 11.60: instalują się, ale gra się nie uruchamia. Fałszywe pakiety PS4 działają.",
"upload_drop_here3": "Upuść lub wybierz pakiety, gry, obrazy dysków, archiwa lub dowolny plik",
"upload_pick_here_mobile3": "Wybierz pakiety, gry, obrazy dysków, archiwa lub dowolny plik",
"upload_drop_kind_pkg": "Pakiety (.pkg, .fpkg): instalowane jako gra, aktualizacja lub DLC, strumieniowane stąd lub najpierw przesyłane.",
"upload_drop_kind_game": "Foldery gier i zrzuty gier: kopiowane na PS5; mogą trafić na ekran główny.",
"upload_drop_kind_image": "Obrazy dysków (.exfat, .ffpkg, .ffpfs, .ffpfsc): kopiowane na PS5; można je zamontować.",
"upload_drop_kind_archive": "Archiwa (.zip, .7z, .rar): wypakowywane na PS5.",
"upload_drop_kind_other": "Każdy inny plik lub folder: kopiowany bez zmian.",
"upload_other_ways": "Albo zainstaluj pakiet:",
"queue_stream_fail_hint": "Strumieniuj i zainstaluj sprawia, że PS5 pobiera pakiet z tego komputera. Jeśli błąd się powtarza, zezwól ps5upload w zaporze tego komputera w sieci lokalnej, aby PS5 mogła się z nim połączyć, albo użyj Ponów przez przesłanie, które najpierw kopiuje pakiet na PS5, a potem go instaluje.",
"err_install_enoent_generic_v2": "Instalator Sony nie mógł otworzyć wymaganego pliku podczas instalacji (błąd kernela 0x80020002 = ENOENT). Jeśli to pakiet DLC, gra podstawowa nie jest jeszcze zainstalowana — zainstaluj najpierw podstawę. W innym przypadku przygotowany pakiet mógł zostać usunięty między przesłaniem a instalacją; ponów próbę instalacji raz. Jeśli błąd się powtarza, zainstaluj go opcją Strumieniuj i zainstaluj w „Prześlij i zainstaluj” — pakiet zostanie wysłany prosto z tego komputera, zamiast najpierw kopiować go na konsolę.",
"upload_convert_first": "Najpierw konwertuj",
"batch_convert_first_hint": "Otwórz zaznaczone gry, foldery i obrazy w Warsztacie, aby najpierw zrobić z nich pakiety, obrazy lub foldery",
"add_sources_pick_folders": "Wybierz jeden lub więcej folderów",
"add_sources_pick_files": "Wybierz jeden lub więcej plików",
"workshop_add_hint": "Wybierz jedną grę, aby ją tu sprawdzić. Kilka gier lub folder z grami trafia do kolejki i jest tworzonych jedna po drugiej.",
"workshop_description_v2": "Zmień format gry, zanim trafi na PS5: zrób pakiet (.pkg), obraz gry (.exfat, .ffpkg albo mniejszy .ffpfsc) lub zwykły folder, albo zajrzyj do obrazu lub pakietu i zmień jego pliki. Praca odbywa się na tym komputerze. Aby wysłać grę bez zmian, użyj {send}.",
"cq_title_v2": "⑤ Kolejka",
"cq_about": "Tworzone jedna po drugiej na tym komputerze, każda tak, jak ustawiono ②, ③ i ④ w chwili dodania. Dodawaj kolejne w ①, nawet w trakcie kolejki; czekającą grę zmienisz jej przyciskiem opcji.",
"cq_then_send": "Gra ustawiona do instalacji lub przesłania po utworzeniu trafia do kolejki {send}.",
"cq_open_send": "Otwórz {send}",
"backup_alike_toggle": "{count} podobnych kopii od {since}. Pokaż każdą, aby przywrócić starszą.",
"add_sources_no_picker": "Ta wersja nie może przeglądać tego komputera — wpisz ścieżkę widoczną dla silnika.",
"collection.empty_body_v2": "Pakiety, foldery gier, obrazy gier i archiwa w nim są wyszukiwane i grupowane według gry. W folderze nic nie jest zmieniane. Pasuje folder na tym urządzeniu, dysk zewnętrzny albo folder na NAS lub serwerze (SMB, FTP, SFTP, WebDAV).",
"collection.add_nas_folder": "Z NAS lub serwera",
"browse_this_device": "To urządzenie…",
"queue_added_waits_for_start": "Dodano do kolejki — naciśnij „Uruchom kolejkę”, aby to wykonać",
"queue_added_waits_for_start_body": "Opcja „Uruchamiaj kolejkę po dodaniu czegoś” jest wyłączona, więc nic się nie zacznie, dopóki nie naciśniesz „Uruchom kolejkę”.",
"queue_auto_start": "Uruchamiaj kolejkę po dodaniu czegoś",
"queue_auto_start_tooltip": "Włączone: „Zainstaluj”, „Prześlij teraz” i „Wyślij” uruchamiają całą kolejkę tej konsoli, po kolei. Wyłączone: tylko dodają do kolejki, a nic nie działa, dopóki nie naciśniesz „Uruchom kolejkę”.",
"queue_auto_start_hint": "Włączone: „Zainstaluj”, „Prześlij teraz” i „Wyślij” uruchamiają całą kolejkę konsoli, po kolei — nie tylko to, co właśnie dodano. Wyłączone: tylko dodają do kolejki, a nic nie działa, dopóki nie naciśniesz „Uruchom kolejkę”. Domyślnie włączone.",
"queue_start_rest_tooltip": "Działają tylko elementy, które uruchomiłeś. To uruchamia też wszystko, co czeka, w kolejności kolejki.",
"queue_start_v2": "Uruchom kolejkę",
