"upload_starts_queue": "Uruchamia kolejkę: to, co już czeka, idzie pierwsze, po kolei",
"upload_waits_for_start": "Dodaje do kolejki. Działa po naciśnięciu „Uruchom kolejkę” (opcja „Uruchamiaj kolejkę po dodaniu czegoś” jest wyłączona)",
